from pathlib import Path
import json,math,re
out=Path('outputs')
def js(path):return json.loads((out/path).read_text())
def jl(path):return [json.loads(x) for x in (out/path).read_text().splitlines()]
cap=js('capacity-study/summary.json');pre=js('preamble-study/summary.json');rel={r['name']:r for r in jl('reliable-runs/results.jsonl')}
four={r['name']:r for r in jl('four-board-study/results.jsonl') if r['formal']}
matched=js('ble-matched-study/hardware-summary.json');tree=js('tree-end-to-end-study/summary.json');assert len(tree)==6
tr={r['name']:r for r in tree};best=min([r for r in tree if r['mode']==3],key=lambda r:(-r['pdr'],r['window300']['mean_ms']))
names={'direct64':'两个电芯直接交给中心','forward64':'经中继逐条转发 64符号','aggregate64':'两条合包 64符号 等待1000μs','aggregate32':'两条合包 32符号 等待1000μs','aggregate64-fast':'两条合包 64符号 等待750μs','aggregate32-fast':'两条合包 32符号 等待750μs'}
def f(v):return f'{v:.3f}'
def pct(v):return f'{100*v:.3f}%'
lines=[]
def p(s):lines.append(s.strip())
def table(h,rows):p('\n'.join(['| '+' | '.join(h)+' |','| '+' | '.join(['---']*len(h))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows]))
p('# 电芯 UWB 组网两日实验汇报')
p('覆盖 2026 年 11 月 3 日至 4 日的实验。本文围绕一个问题展开：**每个电芯每 100 ms 上报一次四字节数据，中心能否在这 100 ms 内收齐 200～300 个电芯的数据？**')
p('## 先看已经得到的结论')
p(f'多节点分时上报、缺包补发、叶节点先交给中继再合包转发，都已经有实板结果。当前采集速度仍达不到 200～300 电芯、100 ms 的要求。真实两跳聚合中，本次表现最好的配置每轮收两个电芯平均需要 **{f(best["group_mean_ms"])} ms**；按同信道、每组两个电芯、各组依次采集推算，200 个约需 **{best["window200"]["mean_ms"]:.0f} ms**，300 个约需 **{best["window300"]["mean_ms"]:.0f} ms**。')
p('已经验证有效的改进包括：按实际业务量缩小数据包、适度缩短前导码、一次通知多个节点并让它们错开发送、把中继已经收集到的数据合包。继续缩短等待或前导码，有时会增加丢包和补发，使总时间变长。后续重点是减少点名和确认帧，并缩短主控处理及控制等待。')
p('## 按这六个问题阅读')
table(['编号','问题','对应实验'],[['1','把程序等待设短，实际发包就会变快多少','等待时间扫描与硬件时间戳测量'],['2','每个电芯只有四字节，缩包和前导码能省多少','载荷与前导码对照'],['3','丢了怎么补，补发要花多少时间','分组确认与故障注入'],['4','多个真实节点能否按安排上报','四板逐个点名与一次通知分时回复'],['5','蓝牙同学的设置能给我们什么参照','同规则模型及UWB对照'],['6','电芯到中继再到中心，全程究竟要多久','四板真实采集与聚合转发']])
p('文中的“电芯节点”使用开发板生成测试数据模拟，没有接入电芯传感器。讨论的是通信过程；传感器采样时间尚未加入。四板中最多同时使用三个数据源。200、300 个节点的数字均注明推算方法。')
p('## 1 程序里填的等待时间与实际发包速度')
p('### 1.1 为什么测')
p('老师要求根据帧间隔反推节点容量，因此先要知道每发一包实际花多久。程序填“等待 150 μs”，只是其中一段等待；组包、主控向无线芯片搬运数据（SPI）和无线发送也需要时间。')
p('### 1.2 怎样测')
p('固定 128 符号前导码、32 字节有效数据，完整数据帧为 59 字节。改变发送结束后的软件等待，用 UWB 芯片的硬件时间戳测量相邻数据包之间的周期。数据阶段不确认、不补发。每组 10 万包，已完成 24 组，各等待值有 2～5 组记录。原计划 42 组未全部完成，本节只汇总已完成记录。')
table(['程序增加的等待 μs','实测发一包的周期 μs','100ms时间预算能安排多少包','发送300包推算 ms'],[[r['gap_us'],f(r['period_us']),r['capacity_100ms'],f(r['estimate_300_ms'])] for r in cap['stage1']])
p('### 1.3 结果说明什么')
p('把主动等待从 500 μs 减到零，实际周期从约 1140 μs 减到 640 μs。**这里的 640 μs 是该程序完成一次数据发送的周期，包含空口和软件处理。** 这解释了为什么等待填零，300 包仍约需 192 ms。')
p('本节容量只回答连续发送的时间预算，尚未加入多节点点名、确认和补发。后续不同程序的周期不能直接用这个 640 μs 代替。早期 32 字节“整帧”的约 429 μs 与这里 32 字节“有效数据”的约 640 μs，帧长度和程序都不同。')
p('## 2 四字节数据和短前导码能省多少')
p('### 2.1 为什么测和怎样测')
p('电芯每次只需少量数据，先把有效数据从 32 字节减到 4 字节，再比较 128、64、32 符号前导码。身份、会话、序号和校验继续保留。32 字节载荷的数据帧为 59 字节，4 字节载荷的数据帧为 31 字节。')
p('前导码是正式数据前的一段同步信号，让接收机发现这包数据并对准接收时刻。“符号”是这里计长度的单位。缩短前导码可以省发送时间，也可能让接收机更难稳定收到。')
p('每种配置双向分别测试直接发送和分组确认补发，共 24 组，每组 10 万包。确认方式是先发 32 个独立数据包，再由接收端用一张缺包清单确认，缺什么补什么，每包最多发送五次。每 300 条数据记录一次耗时。')
table(['有效数据','前导码','不补发时实际周期 μs','不补发时单包到达率','加入确认补发后收300条 ms'],[[str(payload)+' B',prelen,f(next(r for r in pre['groups'] if (r['payload'],r['preamble'],r['mode'])==(payload,prelen,0))['mean_data_period_us']),pct(next(r for r in pre['groups'] if (r['payload'],r['preamble'],r['mode'])==(payload,prelen,0))['final_pdr']),f(next(r for r in pre['groups'] if (r['payload'],r['preamble'],r['mode'])==(payload,prelen,1))['batch_mean_ms'])] for payload in (32,4) for prelen in (128,64,32)])
p('### 2.2 结果说明什么')
p('在 128 符号下，数据量从 32 B 减到 4 B，收齐 300 条的平均时间从 217.113 ms 降到 171.628 ms。继续改为 64 符号，降到 154.891 ms。**缩小数据包和适度缩短前导码确实有效。**')
p('4 B 数据采用 32 符号时，单包发送更快，加入补发后的 300 条平均时间却增至 169.618 ms。原因是该次测试首次丢包更多，补发消耗了节省的时间。确认补发模式的正式记录全部交付，但完整的 300 条批次均超过 100 ms。')
p('因此，本轮后续四板实验把 64 符号作为主要基准，同时保留 32 符号对照。32 符号是历史 128 符号的四分之一，不代表整套通信时间会缩到四分之一。')
